package com.oms.order.service;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class PushSourceServiceTest {
    static JdbcTemplate db;static PushSourceService service;static PushSourceSecrets secrets;
    @BeforeAll static void setup(){String url=System.getenv("ORDER_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/order_workspace_test?"));db=new JdbcTemplate(new DriverManagerDataSource(url,"root",System.getenv("INVENTORY_TEST_PASSWORD")));OrderRepository repository=new OrderRepository();ReflectionTestUtils.setField(repository,"jdbc",db);secrets=new PushSourceSecrets();ReflectionTestUtils.setField(secrets,"key",Base64.getEncoder().encodeToString(new byte[32]));service=new PushSourceService();ReflectionTestUtils.setField(service,"repository",repository);ReflectionTestUtils.setField(service,"secrets",secrets);db.execute("CREATE TABLE IF NOT EXISTS jdp_tb_trade(tid BIGINT PRIMARY KEY,status VARCHAR(64),type VARCHAR(64),seller_nick VARCHAR(200),created DATETIME,modified DATETIME,jdp_modified DATETIME,jdp_response MEDIUMTEXT,KEY idx_seller_time(seller_nick,jdp_modified))");}
    @BeforeEach void reset(){db.update("DELETE FROM oms_order_pull_config");db.update("DELETE FROM oms_order_push_source");}
    Map<String,Object> input(){Map<String,Object> v=new HashMap<>();v.put("source_name","test source");v.put("host","127.0.0.1");v.put("port",13306);v.put("database_name","order_workspace_test");v.put("username","root");v.put("password",System.getenv("INVENTORY_TEST_PASSWORD"));v.put("enabled",0);return v;}
    @Test void credentialsAreEncryptedCompanyBoundAndNotReturned(){Map<String,Object> v=input();String key=service.save("VERIFY",v);String cipher=db.queryForObject("SELECT password_cipher FROM oms_order_push_source",String.class);assertNotEquals(v.get("password"),cipher);assertEquals(v.get("password"),secrets.decrypt("VERIFY",cipher));assertThrows(IllegalArgumentException.class,()->secrets.decrypt("OTHER",cipher));assertFalse(service.list("VERIFY").get(0).containsKey("password_cipher"));assertFalse(service.list("VERIFY").get(0).containsKey("password"));assertTrue(service.list("OTHER").isEmpty());assertThrows(IllegalArgumentException.class,()->service.resolve("OTHER",key));assertThrows(IllegalArgumentException.class,()->service.resolve("VERIFY",key));}
    @Test void blankPasswordPreservesCipherAndRevisionProtectsConcurrentEdits(){Map<String,Object> v=input();String key=service.save("VERIFY",v);v.put("source_key",key);v.put("revision",1);v.put("password","");service.save("VERIFY",v);assertEquals(2,db.queryForObject("SELECT revision FROM oms_order_push_source",Integer.class));assertEquals(System.getenv("INVENTORY_TEST_PASSWORD"),secrets.decrypt("VERIFY",db.queryForObject("SELECT password_cipher FROM oms_order_push_source",String.class)));assertThrows(IllegalArgumentException.class,()->service.save("VERIFY",v));}
    @Test void referencedSourceCannotBeDeletedOrMoved(){Map<String,Object> v=input();String key=service.save("VERIFY",v);db.update("INSERT INTO oms_order_pull_config(company_code,channel_id,channel_name,source_key,seller_nick,initial_time,cursor_time) VALUES ('VERIFY',1,'test',?,'seller',NOW(),NOW())",key);assertThrows(IllegalArgumentException.class,()->service.delete("VERIFY",key));v.put("source_key",key);v.put("revision",1);v.put("database_name","other");assertThrows(IllegalArgumentException.class,()->service.save("VERIFY",v));assertEquals("order_workspace_test",db.queryForObject("SELECT database_name FROM oms_order_push_source",String.class));}
    @Test void enabledConnectionIsTestedAndFailuresDoNotLeakPassword(){Map<String,Object> v=input();v.put("enabled",1);String key=service.save("VERIFY",v);assertTrue(service.configured("VERIFY",key));assertEquals("SUCCESS",service.list("VERIFY").get(0).get("last_test_status"));v.put("password","private-failed-password");String message=assertThrows(IllegalArgumentException.class,()->service.test("VERIFY",v)).getMessage();assertFalse(message.contains("private-failed-password"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_order_push_source",Integer.class));}
    @Test void connectionFieldsRejectUrlInjection(){Map<String,Object> v=input();v.put("host","127.0.0.1/other?user=bad");assertThrows(IllegalArgumentException.class,()->service.save("VERIFY",v));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_order_push_source",Integer.class));}
}
